//! V3-C04: the Rust protocol crate reaches the same verdicts and hashes as the TypeScript contracts on the shared
//! vectors in fixtures/v0.3/protocol/vectors.json (generated by scripts/protocol-vectors.mjs).
use agentos_protocol::canonical::{canonical_json, domain_hash};
use agentos_protocol::dto::{GrantSyncParams, WriteEnvelope};
use agentos_protocol::frame::{json_depth, parse_strict};
use agentos_protocol::params::check_params;
use serde_json::Value;

fn vectors() -> Value {
    let p = concat!(env!("CARGO_MANIFEST_DIR"), "/../../../fixtures/v0.3/protocol/vectors.json");
    serde_json::from_str(&std::fs::read_to_string(p).expect("vectors.json")).unwrap()
}

#[test]
fn canonical_and_domain_hash_match_typescript() {
    let v = vectors();
    for c in v["canonical"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        if let Some(text) = c["text"].as_str() {
            let parsed: Value = serde_json::from_str(text).unwrap();
            assert_eq!(canonical_json(&parsed).is_ok(), c["ok"].as_bool().unwrap(), "{name}");
            continue;
        }
        assert_eq!(canonical_json(&c["value"]).unwrap(), c["canonical"].as_str().unwrap(), "{name}");
        assert_eq!(domain_hash("agentos.test.v1", &c["value"]).unwrap(), c["hash"].as_str().unwrap(), "{name}");
    }
}

#[test]
fn write_envelopes_match_typescript() {
    let v = vectors();
    for c in v["envelopes"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let text = c["text"].as_str().unwrap();
        let verdict = match serde_json::from_str::<WriteEnvelope>(text) {
            Err(_) => false,
            Ok(env) => env.check().is_ok() && domain_hash("agentos.broker.write.v1", &env.hash_body()).map(|h| h == env.request_hash).unwrap_or(false),
        };
        assert_eq!(verdict, c["ok"].as_bool().unwrap(), "envelope {name}");
        if verdict {
            let env: WriteEnvelope = serde_json::from_str(text).unwrap();
            assert_eq!(env.request_hash, c["requestHash"].as_str().unwrap());
        }
    }
}

#[test]
fn grants_match_typescript() {
    let v = vectors();
    for c in v["grants"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let verdict = match serde_json::from_str::<GrantSyncParams>(c["text"].as_str().unwrap()) {
            Err(_) => false,
            Ok(g) => domain_hash("agentos.broker.grant.v1", &g.hash_body()).map(|h| h == g.request_hash).unwrap_or(false),
        };
        assert_eq!(verdict, c["ok"].as_bool().unwrap(), "grant {name}");
    }
}

#[test]
fn provider_params_match_typescript() {
    let v = vectors();
    for c in v["params"].as_array().unwrap() {
        let cap = c["capabilityId"].as_str().unwrap();
        let r = check_params(cap, &c["input"]);
        let ok = c["ok"].as_bool().unwrap();
        assert_eq!(r.is_ok(), ok, "{cap} {}", c["input"]);
        match r {
            Ok(norm) => assert_eq!(canonical_json(&norm).unwrap(), canonical_json(&c["normalized"]).unwrap(), "{cap} normalization"),
            Err(e) => assert_eq!(e.split(':').next().unwrap(), c["code"].as_str().unwrap(), "{cap} error code for {}", c["input"]),
        }
    }
}

#[test]
fn depth_limit_matches_typescript() {
    let v = vectors();
    for c in v["depth"].as_array().unwrap() {
        let text = c["text"].as_str().unwrap();
        assert_eq!(json_depth(text.as_bytes()), c["measured"].as_u64().unwrap() as usize);
        assert_eq!(parse_strict(text.as_bytes()).is_ok(), c["measured"].as_u64().unwrap() <= 8);
    }
}
